def handle(app, svc):
    resp = svc.apply(app)
    result = resp["result"]
    outcome = result["outcome"]
    credit_limit = result.get("credit_limit", 0)

    # Network referral rule: self_employed applicants with requested_limit > 6000
    # must go to manual review even if approved (declines stay declines).
    applicant = app if "employment" in app else app.get("applicant", {})
    self_employed = applicant.get("employment") == "self_employed" or applicant.get("self_employed") is True
    requested_limit = applicant.get("requested_limit", 0)

    if outcome == "approved":
        if self_employed and requested_limit > 6000:
            return {"action": "queue_review", "limit": 0}
        return {"action": "issue", "limit": credit_limit}
    elif outcome == "declined":
        return {"action": "decline", "limit": 0}
    else:  # manual_review
        return {"action": "queue_review", "limit": 0}
